// The title screen.
//
// Shown once the assets are in and before the first run starts. It exists for one
// concrete reason beyond looking like a game: difficulty has to be choosable BEFORE
// you fly, not only after you have died once. A picker that only appeared on the
// game-over screen would mean the first run of every session was always NORMAL.
//
// The simulation is already built and ticking behind this — `startGame` runs from the
// moment boot finishes, so `window.__sw` is available to the smoke and the console
// whether or not anyone has pressed PLAY. What the title gates is the player's
// attention, not the clock. That is a deliberate simplification: a paused-until-play
// world would need a pause concept in the fixed-step loop, which is M5's business.

import type { DifficultyDef } from "@content/difficulty/index.js";
import { createDifficultyPicker, type DifficultyPicker } from "./difficultyPicker.js";

const STYLE = `
.sw-title {
  position: fixed; inset: 0; z-index: 8;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 30px;
  background: radial-gradient(circle at 50% 45%, rgba(10,20,38,0.82), rgba(3,6,12,0.96));
  font: 13px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #cddcf0; user-select: none; -webkit-user-select: none;
  /* The whole screen takes input: it is a modal gate, and a stray tap landing on the
     game behind it would fire a shot into a run the player has not started yet. */
  pointer-events: auto; touch-action: manipulation;
}
.sw-title-name {
  font-size: 40px; letter-spacing: 0.34em; color: #ffd479;
  text-shadow: 0 2px 18px rgba(255,190,90,0.25);
  /* The letter-spacing pushes the text off-centre by one space's width. */
  text-indent: 0.34em;
}
.sw-title-tag { color: #7e8ea8; letter-spacing: 0.2em; font-size: 11px; }
.sw-title-play {
  pointer-events: auto;
  font: 600 16px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.24em; color: #eaf3ff;
  background: rgba(30,70,120,0.85); border: 1px solid #6fa2dd; border-radius: 11px;
  padding: 0 44px; min-height: 56px; min-width: 200px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  transition: background-color 100ms linear, transform 100ms ease-out;
}
.sw-title-play:hover { background: rgba(44,96,158,0.9); }
.sw-title-play:active { transform: scale(0.97); }
.sw-title-hint { color: #63728c; font-size: 11px; letter-spacing: 0.12em; }
`;

export interface TitleScreenOptions {
  readonly initialDifficulty: DifficultyDef;
  /** Called when the player changes difficulty here. No confirm — there is no run yet. */
  readonly onDifficultyChange: (difficulty: DifficultyDef) => void;
  /** Called when PLAY is pressed. The screen removes itself first. */
  readonly onPlay: () => void;
}

export interface TitleScreen {
  readonly root: HTMLElement;
  dispose(): void;
}

export function createTitleScreen(
  options: TitleScreenOptions,
  parent: HTMLElement = document.body,
): TitleScreen {
  const style = document.createElement("style");
  style.textContent = STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-title";

  const name = document.createElement("div");
  name.className = "sw-title-name";
  name.textContent = "SUN WEASEL";

  const tag = document.createElement("div");
  tag.className = "sw-title-tag";
  tag.textContent = "SHAKEDOWN";

  const picker: DifficultyPicker = createDifficultyPicker({
    initial: options.initialDifficulty,
    onChange: options.onDifficultyChange,
  });

  const play = document.createElement("button");
  play.type = "button";
  play.className = "sw-title-play";
  play.dataset.play = "";
  play.textContent = "PLAY";

  const hint = document.createElement("div");
  hint.className = "sw-title-hint";
  hint.textContent = "";

  root.append(name, tag, picker.root, play, hint);
  parent.appendChild(root);

  let disposed = false;
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    picker.dispose();
    root.remove();
    style.remove();
  };

  const onPlay = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    dispose();
    options.onPlay();
  };
  play.addEventListener("click", onPlay);

  return { root, dispose };
}
