// Component definitions.
//
// Registration order is part of the wire format and part of the replay
// fingerprint (see `core/ecs`), so components are declared HERE, in one place, all
// at once, and never conditionally. Adding a component at the end is safe; inserting
// one in the middle changes every fingerprint and every snapshot layout.
//
// Field types are chosen for the wire as much as for the maths: f32 for anything
// spatial (half the bytes of f64 and well beyond the precision a rail shooter's
// world extents need), integers everywhere a value is naturally discrete. Durations
// are stored in TICKS, never in milliseconds — the simulation has no wall clock.

import type { World } from "@core/ecs.js";

export const TransformSchema = {
  /** World position. */
  pos: ["f32", 3],
  /** Orientation as a unit quaternion (x, y, z, w). */
  rot: ["f32", 4],
} as const;

export const MotionSchema = {
  /** Linear velocity, world units per second. */
  vel: ["f32", 3],
} as const;

export const ShipSchema = {
  /** Player slot, 0..5. Also the index into the per-tick input array. */
  slot: "u8",
  /** Current hull. Signed so overkill damage is representable before clamping. */
  health: "i16",
  /** Ticks remaining before this ship may fire again. */
  fireCooldown: "u16",
} as const;

export const ProjectileSchema = {
  /** The ship or enemy that fired this shot, as a packed entity handle. */
  owner: "u32",
  /**
   * Player slot of the owner, carried so scoring survives the owner's death.
   *
   * SIGNED, so an enemy's shot can say -1 rather than borrowing a sentinel from the
   * unsigned range. It was `u8` until enemies existed and -1 became representable
   * state rather than a bug; 255 would have looked like a valid slot to anything that
   * only checked the low bits.
   */
  ownerSlot: "i8",
  damage: "u16",
  /** `Faction` — who this shot may damage. See `sim/faction.ts`. */
  faction: "u8",
} as const;

export const LifetimeSchema = {
  /** Ticks remaining. Reaching zero destroys the entity. */
  ticks: "u16",
} as const;

/** An asteroid or other destructible obstacle. */
export const HazardSchema = {
  /** Collision radius. */
  radius: "f32",
  health: "i16",
  /**
   * Index into the hazard catalog, so an instance can find its own `HazardDef` —
   * what it splits into, how many variants it has — without storing any of it.
   *
   * An index rather than the string id because component columns are TypedArrays and
   * because it is one byte on the wire. The catalog's key order is the mapping; it is
   * therefore part of the content contract, the same way component registration order
   * is part of the wire format.
   */
  defId: "u8",
  /**
   * Which of the def's meshes this instance renders as.
   *
   * Simulation state rather than something the view derives, because two clients must
   * see the same rock. Chosen once at spawn; nothing reads it but the renderer.
   */
  variant: "u8",
} as const;

/** A ship's offset from the rail centre, within the travel box. */
export const BoxOffsetSchema = {
  /** Along the box width axis (the rail frame's binormal). */
  ox: "f32",
  /** Along the box height axis (the rail frame's normal). */
  oy: "f32",
} as const;

/**
 * The aircraft-style aim state, as unit direction vectors.
 *
 * Kept as vectors rather than quaternions to match `FLIGHT_AND_AIM.md`, which is the
 * specification for this model — the reticle-leads/heading-lags relationship is
 * stated there in terms of two directions and the angle between them, and the ship's
 * orientation quaternion is derived from them rather than being the source of truth.
 */
export const AimSchema = {
  /** Where the shot goes. Responds immediately to input. */
  aimDir: ["f32", 3],
  /** Where the nose points. Eases toward `aimDir`. */
  headDir: ["f32", 3],
  /**
   * The ship's up-vector, PARALLEL-TRANSPORTED across each heading change rather
   * than rebuilt from world-up. Rebuilding degenerates and flips when the heading
   * points straight up or down; transport is continuous by construction. This is
   * also the camera's up, so a flip here would be visible as a view roll.
   */
  shipUp: ["f32", 3],
} as const;

/** Per-ship view and aim mode. Simulation state, not renderer state — see world.ts. */
export const ViewStateSchema = {
  /** 0 = free, 1 = forward, 2 = omni. Mirrors `AimMode` in flight.ts. */
  aimMode: "u8",
  /** 0 = cockpit, 1 = third-person. Mirrors `ViewMode` in flight.ts. */
  viewMode: "u8",
  /**
   * Last tick's button bitfield, for rising-edge detection.
   *
   * Edges have to be derived from state rather than from "the previous input
   * frame", because a client rewinding for prediction re-simulates ticks whose
   * predecessors are no longer to hand.
   */
  lastButtons: "u16",
} as const;

/**
 * `EnemySchema.waveId` for an enemy that belongs to no authored wave.
 *
 * 255 rather than -1 because the column is unsigned, and a sentinel rather than a
 * separate "hasWave" flag because a wave index and "no wave" are the same question.
 * A level with 255 waves would collide with it; validation rejects that.
 */
export const NO_WAVE = 255;

/**
 * A hostile ship: moves relative to the rail, aims at the party, and fires back.
 *
 * Everything archetype-level — speed, turn rate, behaviour, weapon, cone — is looked
 * up through `defId`, exactly as a hazard looks up what it splits into. What is stored
 * per instance is only the state that genuinely varies: where it is holding station,
 * where it is pointing, and what it has left.
 */
export const EnemySchema = {
  /** Index into the run's enemy catalog. Same contract as `HazardSchema.defId`. */
  defId: "u8",
  /** Which of the def's meshes this instance renders as. */
  variant: "u8",
  /** Hits remaining, in player-shot counts. */
  health: "i16",
  /** Collision radius, copied from the def so the broadphase needs no lookup. */
  radius: "f32",
  /** Ticks remaining before this enemy may fire again. */
  fireCooldown: "u16",
  /**
   * Where it holds station along the rail. The units depend on its behaviour, which
   * is the one place in the component set that is true — and it is deliberate:
   *
   * - `station` — an ABSOLUTE rail distance. It does not move.
   * - `escort` / `charger` — a LEAD ahead of the party's own `railS`, so the station
   *   follows the party down the rail. A charger decrements it every tick.
   *
   * Storing two columns and leaving one always zero would cost a float per enemy on
   * the wire to avoid one comment.
   */
  station: "f32",
  /** Lateral station on the rail frame's binormal (the box's width axis). */
  ox: "f32",
  /** Lateral station on the rail frame's normal (the box's height axis). */
  oy: "f32",
  /**
   * Which authored wave this enemy belongs to, or `NO_WAVE` for one that belongs to
   * none — a lone spawn, or anything a test placed directly.
   *
   * Stored so clearing a wave can be counted. The alternative, matching survivors by
   * archetype, breaks the moment two waves of the same enemy overlap — which is
   * exactly the case a level author reaches for first.
   */
  waveId: "u8",
  /**
   * Unit facing, eased toward the current target at the def's turn rate.
   *
   * Simulation state rather than something the renderer derives from velocity: an
   * enemy holding station has no velocity to derive from, and the firing cone is
   * measured against this, so a client that disagreed about it would disagree about
   * whether a shot was taken.
   */
  facing: ["f32", 3],
} as const;

/**
 * A collectable dropped by a kill.
 *
 * Expiry rides the existing `lifetime` component rather than a column here: a pickup
 * counting down is exactly what a projectile counting down is, and a second countdown
 * would be a second thing to keep in step with the first.
 */
export const PickupSchema = {
  /** Index into the run's pickup catalog. Same contract as `HazardSchema.defId`. */
  defId: "u8",
  /** Collection radius, copied from the def so the broadphase needs no lookup. */
  radius: "f32",
} as const;

export type Components = ReturnType<typeof defineComponents>;

/**
 * Registers every component on a world and returns the stores.
 *
 * Called exactly once per world, from `createSimWorld`. The returned object is the
 * only handle systems get — there is deliberately no global registry, so a test can
 * stand up several independent worlds (which is precisely what the host-versus-client
 * convergence tests need).
 */
export function defineComponents(ecs: World) {
  return {
    transform: ecs.defineComponent("transform", TransformSchema, 256),
    motion: ecs.defineComponent("motion", MotionSchema, 256),
    ship: ecs.defineComponent("ship", ShipSchema, 8),
    projectile: ecs.defineComponent("projectile", ProjectileSchema, 256),
    lifetime: ecs.defineComponent("lifetime", LifetimeSchema, 256),
    // Appended in M1a step 3. Adding at the END is safe; inserting in the middle
    // would change every fingerprint and every snapshot layout.
    boxOffset: ecs.defineComponent("boxOffset", BoxOffsetSchema, 8),
    aim: ecs.defineComponent("aim", AimSchema, 8),
    viewState: ecs.defineComponent("viewState", ViewStateSchema, 8),
    // Appended in M1a step 4.
    hazard: ecs.defineComponent("hazard", HazardSchema, 128),
    // Appended in M2 step 2.
    enemy: ecs.defineComponent("enemy", EnemySchema, 64),
    // Appended with pickups.
    pickup: ecs.defineComponent("pickup", PickupSchema, 64),
  };
}
