// The transport seam.
//
// Everything above this interface — the host's authoritative loop, the client's
// prediction, the lobby — is written against `Transport` and never against WebRTC.
// That buys three things: single-player runs over a zero-latency loopback with no
// special-casing, multiplayer logic is testable headlessly in one Node process, and
// swapping WebRTC for something else later touches exactly one file.
//
// The two channels mirror what an RTCDataChannel actually offers, because pretending
// otherwise would mean discovering the difference late:
//
//   reliable    ordered, guaranteed  — lobby, join/leave, chat, authoritative events
//   unreliable  unordered, lossy     — input frames and state snapshots
//
// Snapshots go over the unreliable channel deliberately. A snapshot that arrives
// late is worthless (a newer one supersedes it), so retransmitting one only adds
// head-of-line blocking to a stream whose whole job is to be current.

export type PeerId = number;

/** The host is always peer 0. Clients are assigned 1..N as they join. */
export const HOST_PEER: PeerId = 0;

export type Channel = "reliable" | "unreliable";

export interface NetMessage {
  readonly from: PeerId;
  readonly data: Uint8Array;
  readonly channel: Channel;
}

export interface Transport {
  readonly localPeerId: PeerId;
  /** Every peer in the session, including the local one. Sorted, for determinism. */
  readonly peers: readonly PeerId[];
  readonly isHost: boolean;

  send(to: PeerId, data: Uint8Array, channel?: Channel): void;
  /** Sends to every peer except the local one. */
  broadcast(data: Uint8Array, channel?: Channel): void;

  /** Hands over everything received since the last call and empties the inbox. */
  receive(): NetMessage[];

  close(): void;
}

/**
 * A transport with exactly one peer: itself.
 *
 * This is what single-player uses. Messages sent to the local peer land straight
 * in its own inbox, so the game's "collect inputs, send them, apply what arrived"
 * loop is byte-for-byte the same code in single-player and multiplayer. The point
 * is not that this is efficient — it is that there is no second code path to keep
 * in sync.
 */
export class LocalTransport implements Transport {
  readonly localPeerId = HOST_PEER;
  readonly peers: readonly PeerId[] = [HOST_PEER];
  readonly isHost = true;

  private inbox: NetMessage[] = [];
  private closed = false;

  send(to: PeerId, data: Uint8Array, channel: Channel = "reliable"): void {
    if (this.closed || to !== HOST_PEER) return;
    // Copy: the caller is free to reuse its scratch buffer immediately, which a
    // real transport would allow because it serializes on send.
    this.inbox.push({ from: HOST_PEER, data: data.slice(), channel });
  }

  broadcast(_data: Uint8Array, _channel: Channel = "reliable"): void {
    // No remote peers exist, so a broadcast reaches nobody. Deliberately NOT a
    // loopback to self: `broadcast` means "the others", and single-player code
    // that relies on hearing its own broadcast would break the moment a second
    // player joined.
  }

  receive(): NetMessage[] {
    if (this.inbox.length === 0) return [];
    const out = this.inbox;
    this.inbox = [];
    return out;
  }

  close(): void {
    this.closed = true;
    this.inbox.length = 0;
  }
}

// ── In-process test network ───────────────────────────────────────────────────

export interface MemoryNetworkOptions {
  /** Number of peers, including the host. */
  peers: number;
  /** Delivery delay in `step()` calls. Model a 50 ms RTT at 60 Hz as 3 steps. */
  latencySteps?: number;
  /** Extra uniform random delay, in steps, on top of `latencySteps`. */
  jitterSteps?: number;
  /** Drop probability on the UNRELIABLE channel only, in [0, 1]. */
  lossRate?: number;
  /** Seed for loss and jitter, so a failing net test reproduces exactly. */
  seed?: number;
}

interface InFlight {
  deliverAt: number;
  to: PeerId;
  message: NetMessage;
}

/**
 * Wires N transports together inside one process, with configurable latency,
 * jitter, and packet loss.
 *
 * This is how the multiplayer convergence tests run: a host plus five clients in a
 * single Vitest process, no browser and no real network, with loss and jitter driven
 * by a seeded RNG so a desync reproduces on demand. Building it now — before there
 * is any netcode to test — is what keeps the transport interface honest.
 */
export class MemoryNetwork {
  readonly transports: readonly Transport[];
  private readonly inboxes: NetMessage[][];
  private readonly inFlight: InFlight[] = [];
  private readonly lastReliableDelivery = new Map<string, number>();
  private readonly options: Required<MemoryNetworkOptions>;
  private now = 0;
  private rngState: number;

  /** Counters worth asserting on in tests. */
  readonly stats = { sent: 0, delivered: 0, dropped: 0 };

  constructor(options: MemoryNetworkOptions) {
    this.options = {
      latencySteps: 0,
      jitterSteps: 0,
      lossRate: 0,
      seed: 1,
      ...options,
    };
    this.rngState = this.options.seed >>> 0 || 1;
    this.inboxes = Array.from({ length: options.peers }, () => []);
    this.transports = Array.from({ length: options.peers }, (_, id) => this.makeTransport(id));
  }

  /**
   * Advances delivery by one step. Call once per simulated tick in a net test.
   * Messages whose delay has elapsed move into their recipient's inbox.
   */
  step(): void {
    this.now++;
    for (let i = this.inFlight.length - 1; i >= 0; i--) {
      const entry = this.inFlight[i]!;
      if (entry.deliverAt > this.now) continue;
      this.inboxes[entry.to]!.push(entry.message);
      this.inFlight.splice(i, 1);
      this.stats.delivered++;
    }
  }

  /** Delivers everything in flight immediately — useful to settle a test. */
  flush(): void {
    for (const entry of this.inFlight) {
      this.inboxes[entry.to]!.push(entry.message);
      this.stats.delivered++;
    }
    this.inFlight.length = 0;
  }

  get inFlightCount(): number {
    return this.inFlight.length;
  }

  // xorshift32 — this drives loss and jitter, so a seeded test reproduces exactly.
  private random(): number {
    let x = this.rngState;
    x ^= x << 13;
    x ^= x >>> 17;
    x ^= x << 5;
    this.rngState = x >>> 0;
    return this.rngState / 4294967296;
  }

  private enqueue(from: PeerId, to: PeerId, data: Uint8Array, channel: Channel): void {
    if (to === from || to < 0 || to >= this.inboxes.length) return;
    this.stats.sent++;

    if (channel === "unreliable" && this.random() < this.options.lossRate) {
      this.stats.dropped++;
      return;
    }

    const jitter =
      this.options.jitterSteps > 0 ? Math.floor(this.random() * (this.options.jitterSteps + 1)) : 0;
    let deliverAt = this.now + this.options.latencySteps + jitter;

    if (channel === "reliable") {
      // An ordered channel cannot deliver out of order, so jitter may only ever
      // push a reliable message later than its predecessor on the same link —
      // which is exactly how head-of-line blocking manifests in practice.
      const link = `${from}->${to}`;
      const previous = this.lastReliableDelivery.get(link) ?? -1;
      if (deliverAt <= previous) deliverAt = previous + 1;
      this.lastReliableDelivery.set(link, deliverAt);
    }

    this.inFlight.push({ deliverAt, to, message: { from, data: data.slice(), channel } });
  }

  // Arrow functions here capture the network lexically, so there is no `this`
  // rebinding to worry about when a caller destructures a transport off the array.
  private makeTransport(id: PeerId): Transport {
    let closed = false;

    return {
      localPeerId: id,
      peers: Array.from({ length: this.inboxes.length }, (_, i) => i),
      isHost: id === HOST_PEER,

      send: (to: PeerId, data: Uint8Array, channel: Channel = "reliable"): void => {
        if (!closed) this.enqueue(id, to, data, channel);
      },

      broadcast: (data: Uint8Array, channel: Channel = "reliable"): void => {
        if (closed) return;
        for (let peer = 0; peer < this.inboxes.length; peer++) {
          if (peer !== id) this.enqueue(id, peer, data, channel);
        }
      },

      receive: (): NetMessage[] => {
        const inbox = this.inboxes[id]!;
        return inbox.length === 0 ? [] : inbox.splice(0, inbox.length);
      },

      close: (): void => {
        closed = true;
        this.inboxes[id]!.length = 0;
      },
    };
  }
}
