// Touch controls — the DOM half.
//
// Elements, pointer listeners, and drawing. Every decision lives in `touch.ts`; this
// converts events into calls on the model and writes the model's state back out as
// transforms. Nothing here computes an axis.
//
// Two things about it are less obvious than they look:
//
// `touch-action: none` on the overlay is what stops the browser from claiming the
// gesture. Without it a downward drag on the left half scrolls the page (or triggers
// pull-to-refresh on Android) and the pointer events STOP ARRIVING mid-drag — the
// stick sticks, the ship flies into a wall, and it reads as an input bug rather than a
// CSS one. `preventDefault` on pointerdown alone does not cover it; the browser
// decides scrolling from `touch-action` before the listener runs.
//
// Pointer capture is likewise not decoration. A thumb that starts on the stick and
// slides off the overlay's bounds — or over the HUD, or past the screen edge — stops
// delivering `pointermove` to this element without it, and the last known position
// becomes a permanently held stick.

import { TouchControls, type Zone } from "./touch.js";

const STYLE = `
.sw-touch {
  position: fixed; inset: 0; z-index: 5;
  touch-action: none; -webkit-user-select: none; user-select: none;
  -webkit-tap-highlight-color: transparent;
  font: 600 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.1em;
}
/* The overlay itself must not swallow anything when touch is off. */
.sw-touch.sw-touch-off { display: none; }

.sw-touch-stick, .sw-touch-knob, .sw-touch-home {
  position: absolute; border-radius: 50%; pointer-events: none;
  transform: translate(-50%, -50%);
  will-change: transform, opacity;
}
.sw-touch-stick {
  border: 2px solid rgba(125,180,255,0.45);
  background: rgba(10,20,38,0.28);
  opacity: 0; transition: opacity 120ms linear;
}
.sw-touch-knob {
  background: rgba(160,205,255,0.5);
  border: 1px solid rgba(200,228,255,0.7);
  opacity: 0; transition: opacity 120ms linear;
}
/* The idle hint: where to put your thumb, before you have put it anywhere. */
.sw-touch-home {
  border: 1px dashed rgba(125,160,210,0.35);
  opacity: 0.5; transition: opacity 160ms linear;
}
.sw-touch-active .sw-touch-stick, .sw-touch-active .sw-touch-knob { opacity: 1; }
.sw-touch-active .sw-touch-home { opacity: 0; }

.sw-touch-chip {
  position: absolute; border-radius: 12px;
  border: 1px solid rgba(125,160,210,0.4);
  background: rgba(10,18,34,0.42);
  color: #b6c9e4;
  display: flex; align-items: center; justify-content: center;
  pointer-events: none;
  transition: background-color 90ms linear, color 90ms linear, transform 90ms ease-out;
}
.sw-touch-chip.pressed {
  background: rgba(80,150,225,0.65); color: #f0f7ff; transform: scale(0.94);
}
/* A hint that the right half fires, shown until the player has fired once. */
.sw-touch-firehint {
  position: absolute; right: 0; top: 50%; width: 50%;
  transform: translateY(-50%);
  text-align: center; color: rgba(150,180,215,0.55);
  pointer-events: none; transition: opacity 400ms linear;
}
.sw-touch-firehint.gone { opacity: 0; }
`;

const CHIP_LABELS: Record<"boost" | "brake" | "view" | "aim", string> = {
  boost: "BOOST",
  brake: "BRAKE",
  view: "VIEW",
  aim: "AIM",
};

export interface TouchView {
  readonly root: HTMLElement;
  readonly controls: TouchControls;
  /** Re-reads the viewport and re-lays-out the chips. */
  resize(): void;
  /** Repaints stick and chip state. Called once per rendered frame. */
  draw(): void;
  dispose(): void;
}

/** Reads a CSS `env(safe-area-inset-*)` value, in pixels. */
function safeAreaInset(root: HTMLElement, side: "bottom" | "right" | "left"): number {
  const probe = getComputedStyle(root).getPropertyValue(`--sw-safe-${side}`);
  const value = Number.parseFloat(probe);
  return Number.isFinite(value) ? value : 0;
}

export function createTouchView(parent: HTMLElement = document.body): TouchView {
  const style = document.createElement("style");
  // The insets are declared as custom properties so `env()` is resolved by the browser
  // and read back as a number — `env()` is not available to script any other way.
  style.textContent =
    `.sw-touch { --sw-safe-bottom: env(safe-area-inset-bottom, 0px);` +
    ` --sw-safe-right: env(safe-area-inset-right, 0px);` +
    ` --sw-safe-left: env(safe-area-inset-left, 0px); }` +
    STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-touch";

  const home = document.createElement("div");
  home.className = "sw-touch-home";
  const ring = document.createElement("div");
  ring.className = "sw-touch-stick";
  const knob = document.createElement("div");
  knob.className = "sw-touch-knob";
  const fireHint = document.createElement("div");
  fireHint.className = "sw-touch-firehint";
  fireHint.textContent = "TAP OR HOLD TO FIRE";
  root.append(home, ring, knob, fireHint);

  const chips = {} as Record<"boost" | "brake" | "view" | "aim", HTMLElement>;
  for (const name of ["view", "aim", "boost", "brake"] as const) {
    const el = document.createElement("div");
    el.className = "sw-touch-chip";
    el.dataset.chip = name;
    el.textContent = CHIP_LABELS[name];
    root.appendChild(el);
    chips[name] = el;
  }

  parent.appendChild(root);

  const controls = new TouchControls(window.innerWidth, window.innerHeight);
  let hasFired = false;

  const resize = () => {
    controls.resize(
      window.innerWidth,
      window.innerHeight,
      safeAreaInset(root, "bottom"),
      safeAreaInset(root, "right"),
      safeAreaInset(root, "left"),
    );
    const l = controls.layout;
    const size = `${l.stickRadius * 2}px`;
    home.style.width = size;
    home.style.height = size;
    home.style.left = `${l.stickHome.x}px`;
    home.style.top = `${l.stickHome.y}px`;
    ring.style.width = size;
    ring.style.height = size;
    knob.style.width = `${l.stickRadius * 0.55}px`;
    knob.style.height = `${l.stickRadius * 0.55}px`;

    for (const name of ["view", "aim", "boost", "brake"] as const) {
      const rect = l.chips[name];
      const el = chips[name];
      el.style.left = `${rect.x}px`;
      el.style.top = `${rect.y}px`;
      el.style.width = `${rect.width}px`;
      el.style.height = `${rect.height}px`;
    }
  };

  // ── Pointer plumbing ────────────────────────────────────────────────────────
  const onDown = (e: PointerEvent) => {
    // Keeps the browser from turning the press into a scroll, a text selection, or —
    // on iOS — a double-tap zoom that leaves the game at 2× and unplayable.
    e.preventDefault();
    root.setPointerCapture(e.pointerId);
    controls.down(e.pointerId, e.clientX, e.clientY);
    if (controls.zoneAt(e.clientX, e.clientY) === "fire" && !hasFired) {
      hasFired = true;
      fireHint.classList.add("gone");
    }
  };
  const onMove = (e: PointerEvent) => {
    e.preventDefault();
    controls.move(e.pointerId, e.clientX, e.clientY);
  };
  const onUp = (e: PointerEvent) => {
    e.preventDefault();
    controls.up(e.pointerId);
    if (root.hasPointerCapture(e.pointerId)) root.releasePointerCapture(e.pointerId);
  };
  // Backgrounding the app swallows pointerup. Without this the ship keeps flying with
  // the stick pinned, and the player comes back to a wreck they never flew into.
  const onHide = () => {
    if (document.visibilityState === "hidden") controls.cancelAll();
  };

  const onBlur = () => controls.cancelAll();

  root.addEventListener("pointerdown", onDown);
  root.addEventListener("pointermove", onMove);
  root.addEventListener("pointerup", onUp);
  root.addEventListener("pointercancel", onUp);
  document.addEventListener("visibilitychange", onHide);
  window.addEventListener("blur", onBlur);

  resize();

  let wasActive = false;
  const pressed = new Set<Zone>();

  return {
    root,
    controls,
    resize,

    draw() {
      const stick = controls.stick();
      if (stick.active !== wasActive) {
        root.classList.toggle("sw-touch-active", stick.active);
        wasActive = stick.active;
      }
      if (stick.active) {
        ring.style.left = `${stick.originX}px`;
        ring.style.top = `${stick.originY}px`;
        knob.style.left = `${stick.originX + stick.knobX}px`;
        knob.style.top = `${stick.originY + stick.knobY}px`;
      }

      // Only touch a class when it actually changed — this runs every frame.
      const held = controls.heldZones();
      for (const name of ["view", "aim", "boost", "brake"] as const) {
        const isHeld = held.has(name);
        if (isHeld === pressed.has(name)) continue;
        chips[name].classList.toggle("pressed", isHeld);
        if (isHeld) pressed.add(name);
        else pressed.delete(name);
      }
    },

    dispose() {
      root.removeEventListener("pointerdown", onDown);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerup", onUp);
      root.removeEventListener("pointercancel", onUp);
      document.removeEventListener("visibilitychange", onHide);
      window.removeEventListener("blur", onBlur);
      root.remove();
      style.remove();
    },
  };
}
