// Where the player's difficulty choice lives between runs.
//
// Deliberately tiny, and deliberately NOT the meta-save. M3's save is a versioned
// document with a migration chain; this is one string, and coupling the two now would
// mean the difficulty picker could not ship until the save format did.
//
// Precedence is URL, then what was last chosen, then the default. The URL winning
// matters for sharing a link and for the smoke, which needs to drive a known
// difficulty without depending on whatever the previous run happened to leave behind.

import {
  DEFAULT_DIFFICULTY,
  DIFFICULTIES,
  difficultyById,
  type DifficultyDef,
} from "@content/difficulty/index.js";

const KEY = "sw.difficulty";

/** Reads the stored choice. Any failure falls back rather than throwing. */
export function loadDifficulty(search = window.location.search): DifficultyDef {
  const requested = new URLSearchParams(search).get("difficulty");
  if (requested) {
    // Accepts the bare name as well as the full id, so `?difficulty=easy` works —
    // nobody is going to type `?difficulty=difficulty.easy`. An unrecognised value
    // falls through to the stored choice rather than silently meaning NORMAL.
    const name = requested.toLowerCase();
    const id = name.startsWith("difficulty.") ? name : `difficulty.${name}`;
    const found = DIFFICULTIES[id];
    if (found) return found;
  }

  try {
    return difficultyById(window.localStorage.getItem(KEY));
  } catch {
    // Private browsing, or storage disabled. Not worth a broken boot.
    return DEFAULT_DIFFICULTY;
  }
}

export function saveDifficulty(difficulty: DifficultyDef): void {
  try {
    window.localStorage.setItem(KEY, difficulty.id);
  } catch {
    // Nothing to do and nothing worth telling the player — the run still works, the
    // choice just will not outlive the tab.
  }
}
