// A small sparse-set ECS with TypedArray columns.
//
// Why hand-rolled rather than bitECS or an archetype ECS: the entire point of the
// storage layer here is that a snapshot is a set of array slices we control the
// byte layout of, because that layout is what goes over the wire delta-compressed.
// Off-the-shelf ECS serializers do not give us that, and the scale involved
// (6 ships, a few hundred projectiles and hazards) does not need archetype
// sophistication. This file should stay small; if it starts growing features,
// that is a signal the gameplay wants something the storage should not know about.
//
// Layout, per component:
//   sparse[entityIndex] -> dense row, or -1
//   dense[row]          -> the full entity handle
//   columns.foo[row * arity + k]
//
// Removal is swap-with-last, so rows are not stable across a `remove`. Iteration
// order therefore depends on the operation history — which is deterministic given
// the same history, but it does mean you must not mutate a store while iterating
// it. Use `World.destroyLater()` and let the tick flush it.

export type FieldType = "f32" | "f64" | "i8" | "u8" | "i16" | "u16" | "i32" | "u32";
export type FieldSpec = FieldType | readonly [FieldType, number];
export type Schema = Readonly<Record<string, FieldSpec>>;

type ArrayFor<T extends FieldType> = T extends "f32"
  ? Float32Array
  : T extends "f64"
    ? Float64Array
    : T extends "i8"
      ? Int8Array
      : T extends "u8"
        ? Uint8Array
        : T extends "i16"
          ? Int16Array
          : T extends "u16"
            ? Uint16Array
            : T extends "i32"
              ? Int32Array
              : T extends "u32"
                ? Uint32Array
                : never;

export type ColumnsOf<S extends Schema> = {
  -readonly [K in keyof S]: S[K] extends readonly [infer T, number]
    ? T extends FieldType
      ? ArrayFor<T>
      : never
    : S[K] extends FieldType
      ? ArrayFor<S[K]>
      : never;
};

export type AnyTypedArray =
  | Float32Array
  | Float64Array
  | Int8Array
  | Uint8Array
  | Int16Array
  | Uint16Array
  | Int32Array
  | Uint32Array;

const CTORS = {
  f32: Float32Array,
  f64: Float64Array,
  i8: Int8Array,
  u8: Uint8Array,
  i16: Int16Array,
  u16: Uint16Array,
  i32: Int32Array,
  u32: Uint32Array,
} as const;

const fieldType = (spec: FieldSpec): FieldType => (Array.isArray(spec) ? spec[0] : spec) as FieldType;
const fieldArity = (spec: FieldSpec): number => (Array.isArray(spec) ? (spec[1] as number) : 1);

// ── Entity handles ────────────────────────────────────────────────────────────
// Packed as `index | generation << 20`, kept under 31 bits so handles stay SMIs.
// The generation makes a stale handle detectable after the index is recycled.

const INDEX_BITS = 20;
const MAX_INDEX = (1 << INDEX_BITS) - 1;
const GEN_MASK = 0x7ff;

export type Entity = number & { readonly __entity?: unique symbol };
export const NULL_ENTITY = 0 as Entity;

export const entityIndex = (e: Entity): number => e & MAX_INDEX;
export const entityGeneration = (e: Entity): number => (e >>> INDEX_BITS) & GEN_MASK;
const packEntity = (index: number, generation: number): Entity =>
  ((index | ((generation & GEN_MASK) << INDEX_BITS)) >>> 0) as Entity;

// ── Component store ───────────────────────────────────────────────────────────

export class ComponentStore<S extends Schema> {
  readonly name: string;
  readonly schema: S;
  readonly columns: ColumnsOf<S>;
  readonly arity: Readonly<Record<keyof S, number>>;

  /** dense row -> entity handle. Only `[0, count)` is meaningful. */
  dense: Uint32Array;
  /** entity index -> dense row, or -1. */
  private sparse: Int32Array;
  private capacity: number;
  count = 0;

  constructor(name: string, schema: S, capacity = 64, sparseCapacity = 1024) {
    this.name = name;
    this.schema = schema;
    this.capacity = Math.max(1, capacity);
    this.dense = new Uint32Array(this.capacity);
    this.sparse = new Int32Array(sparseCapacity).fill(-1);

    const columns = {} as ColumnsOf<S>;
    const arity = {} as Record<keyof S, number>;
    for (const key of Object.keys(schema) as (keyof S)[]) {
      const spec = schema[key]!;
      const n = fieldArity(spec);
      arity[key] = n;
      const Ctor = CTORS[fieldType(spec)];
      (columns as Record<string, AnyTypedArray>)[key as string] = new Ctor(this.capacity * n);
    }
    this.columns = columns;
    this.arity = arity;
  }

  has(entity: Entity): boolean {
    const i = entityIndex(entity);
    if (i >= this.sparse.length) return false;
    const row = this.sparse[i]!;
    return row >= 0 && row < this.count && this.dense[row] === entity;
  }

  /** Dense row for `entity`, or -1 if absent. */
  row(entity: Entity): number {
    return this.has(entity) ? this.sparse[entityIndex(entity)]! : -1;
  }

  /**
   * Adds `entity` and returns its row. Fields are zeroed. Re-adding an entity that
   * is already present returns its existing row WITHOUT clearing it, so callers can
   * treat `add` as "ensure present".
   */
  add(entity: Entity): number {
    const existing = this.row(entity);
    if (existing >= 0) return existing;

    const i = entityIndex(entity);
    if (i >= this.sparse.length) this.growSparse(i + 1);
    if (this.count >= this.capacity) this.growDense(this.count + 1);

    const row = this.count++;
    this.sparse[i] = row;
    this.dense[row] = entity;
    this.clearRow(row);
    return row;
  }

  /** Removes `entity` via swap-with-last. Returns true if it was present. */
  remove(entity: Entity): boolean {
    const row = this.row(entity);
    if (row < 0) return false;

    const last = --this.count;
    if (row !== last) {
      const moved = this.dense[last]! as Entity;
      this.dense[row] = moved;
      this.sparse[entityIndex(moved)] = row;
      this.copyRow(last, row);
    }
    this.sparse[entityIndex(entity)] = -1;
    this.clearRow(last);
    return true;
  }

  clear(): void {
    for (let r = 0; r < this.count; r++) this.sparse[entityIndex(this.dense[r]! as Entity)] = -1;
    this.count = 0;
  }

  /** Iterates live rows. Do not add or remove from this store inside `fn`. */
  each(fn: (entity: Entity, row: number) => void): void {
    for (let row = 0; row < this.count; row++) fn(this.dense[row]! as Entity, row);
  }

  /**
   * `[field name, column, arity]` in schema declaration order.
   *
   * The generic accessor used by fingerprinting and (later) snapshot serialization,
   * so those never have to reach into private state. Order comes from the schema
   * object's key order, which is part of the wire format — see components.ts.
   */
  columnEntries(): Array<[string, AnyTypedArray, number]> {
    return (Object.keys(this.schema) as string[]).map((key) => [
      key,
      (this.columns as Record<string, AnyTypedArray>)[key]!,
      this.arity[key as keyof S],
    ]);
  }

  private clearRow(row: number): void {
    for (const key of Object.keys(this.schema) as (keyof S)[]) {
      const n = this.arity[key];
      const col = (this.columns as Record<string, AnyTypedArray>)[key as string]!;
      col.fill(0, row * n, row * n + n);
    }
  }

  private copyRow(from: number, to: number): void {
    for (const key of Object.keys(this.schema) as (keyof S)[]) {
      const n = this.arity[key];
      const col = (this.columns as Record<string, AnyTypedArray>)[key as string]!;
      for (let k = 0; k < n; k++) col[to * n + k] = col[from * n + k]!;
    }
  }

  private growSparse(needed: number): void {
    let size = this.sparse.length;
    while (size < needed) size *= 2;
    const next = new Int32Array(size).fill(-1);
    next.set(this.sparse);
    this.sparse = next;
  }

  private growDense(needed: number): void {
    let size = this.capacity;
    while (size < needed) size *= 2;
    const dense = new Uint32Array(size);
    dense.set(this.dense);
    this.dense = dense;

    for (const key of Object.keys(this.schema) as (keyof S)[]) {
      const n = this.arity[key];
      const spec = this.schema[key]!;
      const Ctor = CTORS[fieldType(spec)];
      const next = new Ctor(size * n);
      next.set((this.columns as Record<string, AnyTypedArray>)[key as string]! as never);
      (this.columns as Record<string, AnyTypedArray>)[key as string] = next;
    }
    this.capacity = size;
  }
}

// ── World ─────────────────────────────────────────────────────────────────────

export class World {
  private generations: Uint16Array;
  private alive: Uint8Array;
  private freeList: number[] = [];
  private nextIndex = 1; // index 0 is reserved for NULL_ENTITY
  private stores: ComponentStore<Schema>[] = [];
  private pendingDestroy: Entity[] = [];

  constructor(capacity = 1024) {
    this.generations = new Uint16Array(capacity);
    this.alive = new Uint8Array(capacity);
  }

  /**
   * Registers a component. Stores are kept in registration order, which is the
   * order they are hashed and serialized in — so registration order is part of the
   * wire format. Register components in one place, at startup, never conditionally.
   */
  defineComponent<S extends Schema>(name: string, schema: S, capacity = 64): ComponentStore<S> {
    const store = new ComponentStore(name, schema, capacity, this.generations.length);
    this.stores.push(store as unknown as ComponentStore<Schema>);
    return store;
  }

  get componentStores(): readonly ComponentStore<Schema>[] {
    return this.stores;
  }

  create(): Entity {
    let index: number;
    if (this.freeList.length > 0) {
      index = this.freeList.pop()!;
    } else {
      index = this.nextIndex++;
      if (index > MAX_INDEX) throw new Error("ECS: entity index space exhausted");
      if (index >= this.generations.length) this.growEntities(index + 1);
    }
    this.alive[index] = 1;
    return packEntity(index, this.generations[index]!);
  }

  isAlive(entity: Entity): boolean {
    const i = entityIndex(entity);
    return (
      i > 0 &&
      i < this.alive.length &&
      this.alive[i] === 1 &&
      this.generations[i] === entityGeneration(entity)
    );
  }

  /** Immediate destroy. Unsafe while iterating a store — prefer `destroyLater`. */
  destroy(entity: Entity): void {
    if (!this.isAlive(entity)) return;
    const i = entityIndex(entity);
    for (const store of this.stores) store.remove(entity);
    this.alive[i] = 0;
    this.generations[i] = (this.generations[i]! + 1) & GEN_MASK;
    this.freeList.push(i);
  }

  /**
   * Queues `entity` for destruction at the next `flushDestroyed()`. This is the
   * safe call from inside a system, since destroying during iteration would swap a
   * not-yet-visited row into a slot the loop has already passed.
   */
  destroyLater(entity: Entity): void {
    if (this.isAlive(entity)) this.pendingDestroy.push(entity);
  }

  /** Applies queued destroys. Called once per tick, after all systems have run. */
  flushDestroyed(): number {
    const n = this.pendingDestroy.length;
    if (n === 0) return 0;
    for (const e of this.pendingDestroy) this.destroy(e);
    this.pendingDestroy.length = 0;
    return n;
  }

  get pendingDestroyCount(): number {
    return this.pendingDestroy.length;
  }

  /** Live entity count. O(1) — tracked by the free list, not by scanning. */
  get entityCount(): number {
    return this.nextIndex - 1 - this.freeList.length;
  }

  /**
   * The allocator's own state, for fingerprinting and snapshots.
   *
   * This is NOT redundant with the component data. Two worlds can hold an identical
   * set of live entities and still be in different states, because the free list
   * decides which handle the NEXT spawn receives — and its order depends on the
   * order things were destroyed in. Destroy A then B, versus B then A, leaves the
   * same survivors but hands out different ids afterwards.
   *
   * Leaving this out of the fingerprint made two such worlds compare equal and then
   * diverge on the next spawn, which is the worst possible failure mode for a desync
   * check: silent until long after the cause.
   */
  allocatorState(): {
    nextIndex: number;
    /** Generation counter per slot, including recycled ones. */
    generations: Uint16Array;
    /** Recycled indices, in the order they will be handed back out. */
    freeList: readonly number[];
  } {
    return {
      nextIndex: this.nextIndex,
      generations: this.generations.subarray(0, this.nextIndex),
      freeList: this.freeList,
    };
  }

  reset(): void {
    for (const store of this.stores) store.clear();
    this.alive.fill(0);
    this.generations.fill(0);
    this.freeList.length = 0;
    this.pendingDestroy.length = 0;
    this.nextIndex = 1;
  }

  private growEntities(needed: number): void {
    let size = this.generations.length;
    while (size < needed) size *= 2;
    const gens = new Uint16Array(size);
    gens.set(this.generations);
    this.generations = gens;
    const alive = new Uint8Array(size);
    alive.set(this.alive);
    this.alive = alive;
  }
}

/**
 * Calls `fn` for every entity present in ALL of the given stores, driving the
 * iteration from whichever store is smallest. Do not add or remove components
 * inside `fn`; use `World.destroyLater()`.
 */
export function query(
  stores: readonly ComponentStore<Schema>[],
  fn: (entity: Entity) => void,
): void {
  if (stores.length === 0) return;
  let driver = stores[0]!;
  for (const s of stores) if (s.count < driver.count) driver = s;

  for (let row = 0; row < driver.count; row++) {
    const entity = driver.dense[row]! as Entity;
    let all = true;
    for (const s of stores) {
      if (s !== driver && !s.has(entity)) {
        all = false;
        break;
      }
    }
    if (all) fn(entity);
  }
}
