// Flight and aim state.
//
// Re-derived from `pewpew/docs/FLIGHT_AND_AIM.md`, which is the specification for
// this module — not the old implementation. The model in one paragraph:
//
//   The rail carries a moving centre point forward. The ship slides within a travel
//   BOX around that centre. Aiming is aircraft-style and two-part: a RETICLE that
//   responds immediately to input, and a ship HEADING that eases toward it, so the
//   body visibly catches up. Both are carried through the rail's tangent rotation
//   each tick, so hands-off tracks a curving rail instead of lagging it. The ship's
//   up-vector is parallel-transported rather than rebuilt from world-up, which is
//   what makes crossing the vertical continuous instead of a flip.
//
// The one deliberate change from the original: input is relative to the ship's own
// VIEW BASIS, which is simulation state here, rather than to `camera.matrixWorld`.
// The renderer's camera is slaved to that basis. Same feel, deterministic, and it
// works for six ships at once.

import { Vec3 } from "@core/math/index.js";
import type { Entity } from "@core/ecs.js";
import { CONE_ANGLE, FWD_CONE, OMNI_CONE } from "@content/tuning/flight.js";
import type { SimWorld } from "./world.js";

/** How far off rail-forward the reticle may point. */
export type AimMode = "free" | "forward" | "omni";

export type ViewMode = "cockpit" | "third";

/** Stored as small integers in the `viewState` component; these are the mappings. */
export const AIM_MODES: readonly AimMode[] = ["free", "forward", "omni"];
export const VIEW_MODES: readonly ViewMode[] = ["cockpit", "third"];

export const aimModeIndex = (mode: AimMode): number => AIM_MODES.indexOf(mode);
export const viewModeIndex = (mode: ViewMode): number => VIEW_MODES.indexOf(mode);

/**
 * How far off rail-forward a mode lets the reticle point.
 *
 * Lives here rather than in `systems/flight.ts` because it has a SECOND caller now:
 * `systems/enemies.ts` asks the same question in the other direction — whether a ship
 * could bring its guns to bear on a given enemy — and the two must not be able to
 * disagree about what a mode allows. It is the aim limit and the return-fire limit
 * both, from one definition.
 */
export const coneFor = (mode: AimMode): number =>
  mode === "omni" ? OMNI_CONE : mode === "forward" ? FWD_CONE : CONE_ANGLE;

/** A ship's flight state, in world space. */
export interface FlightState {
  /** Offset from the rail centre along the box's width axis. */
  ox: number;
  /** Offset along the box's height axis. */
  oy: number;
  /** Where the shot goes. Leads under input. Unit. */
  aim: Vec3;
  /** Where the nose points. Eases toward `aim`. Unit. */
  head: Vec3;
  /** Transported up-vector. Also the camera's up, which is why it must not flip. */
  up: Vec3;
  aimMode: AimMode;
  viewMode: ViewMode;
}

export const createFlightState = (): FlightState => ({
  ox: 0,
  oy: 0,
  aim: new Vec3(1, 0, 0),
  head: new Vec3(1, 0, 0),
  up: new Vec3(0, 1, 0),
  aimMode: "free",
  viewMode: "cockpit",
});

/**
 * The basis input is interpreted against.
 *
 * Steering rotates the reticle about `up` and `right`, so "left" always means left on
 * screen no matter which way the ship faces — including backward at an omni stop.
 * Derived from the ship's heading and transported up, never from a renderer camera.
 */
export interface ViewBasis {
  readonly forward: Vec3;
  readonly right: Vec3;
  readonly up: Vec3;
}

export interface MutableViewBasis {
  forward: Vec3;
  right: Vec3;
  up: Vec3;
}

/**
 * Reads a ship's flight state into `out`. Returns false if the entity has none.
 *
 * Used by the specs and by the renderer, which places the cockpit and chase cameras
 * from `head`/`up` rather than deriving its own.
 */
export function readFlight(world: SimWorld, entity: Entity, out: FlightState): boolean {
  const { boxOffset, aim, viewState } = world.components;
  const b = boxOffset.row(entity);
  const a = aim.row(entity);
  const v = viewState.row(entity);
  if (b < 0 || a < 0 || v < 0) return false;

  out.ox = boxOffset.columns.ox[b]!;
  out.oy = boxOffset.columns.oy[b]!;
  out.aim.readFrom(aim.columns.aimDir, a * 3);
  out.head.readFrom(aim.columns.headDir, a * 3);
  out.up.readFrom(aim.columns.shipUp, a * 3);
  // The component holds the player's PREFERENCE; a stop can force a mode over it.
  // Reporting the effective mode keeps callers from having to know about stops.
  out.aimMode = world.forcedAimMode ?? AIM_MODES[viewState.columns.aimMode[v]!] ?? "free";
  out.viewMode = VIEW_MODES[viewState.columns.viewMode[v]!] ?? "cockpit";
  return true;
}

/**
 * Computes the view basis a ship's input is interpreted against.
 *
 * Separate from `readFlight` because the renderer needs it too, and because the
 * "steering is view-relative" spec asserts it directly rather than inferring it from
 * where a projected reticle landed on screen.
 *
 * `right = forward × up` is the right-handed camera convention: looking down -Z with
 * up +Y gives right +X.
 */
export function viewBasisFor(state: FlightState, out: MutableViewBasis): ViewBasis {
  out.forward.copy(state.head).normalize();
  out.up.copy(state.up).orthogonalize(out.forward);
  if (out.up.lengthSq() < 1e-12) {
    // Degenerate only if `up` collapsed onto the heading, which transport prevents;
    // fall back to any perpendicular so the basis stays usable rather than NaN.
    out.up.set(0, 1, 0).orthogonalize(out.forward);
    if (out.up.lengthSq() < 1e-12) out.up.set(1, 0, 0).orthogonalize(out.forward);
  }
  out.up.normalize();
  out.right.crossVectors(out.forward, out.up).normalize();
  return out;
}
