// The weapon catalog.
//
// The numbers are the ones `systems/firing.ts` carried as module constants through M0
// and M1, moved here so this is a refactor of WHERE they live rather than a retune of
// what they are.
//
// ⚠️ ONE DELIBERATE CHANGE: `damage` is 1, not the old 10. Hazard health used to be a
// flat 1 against a damage of 10, so the two numbers only had to be in the right order
// relative to each other and neither meant anything on its own. With tiered rocks,
// health is now the SHOT COUNT to break something — 1, 2, 4 — which is a number an
// author can reason about. That only works if a shot does 1. Nothing else moved.
//
// From M3 a run resolves these through the upgrade/stat fold — `ShipStats` computed
// once at run start by folding `UpgradeDef` modifiers over the base def. The sim still
// only ever sees a resolved `WeaponDef`, which is what keeps upgrades out of it.

import type { WeaponCatalog, WeaponDef } from "../schemas/weapon.js";

export const PULSE_LASER: WeaponDef = {
  id: "weapon.pulse",
  fireIntervalTicks: 9,
  projectileLifetimeTicks: 90,
  projectileSpeed: 120,
  damage: 1,
  spread: 0.02,
  muzzleForward: 1.5,
};

/**
 * What enemies shoot back with.
 *
 * The numbers read differently from the pulse laser's because they are aimed at a
 * different scale: `damage` here is against SHIP health, which is 100 points, whereas
 * the laser's 1 is against a hazard's shot-count health. Twelve hits to down a ship,
 * against a fire interval slow enough that a single drone is a nuisance and four of
 * them are a problem. Slower and shorter-lived than the player's bolt as well, so a
 * shot is something you can see coming and fly around.
 */
export const ENEMY_BLASTER: WeaponDef = {
  id: "weapon.enemyBlaster",
  fireIntervalTicks: 45,
  projectileLifetimeTicks: 120,
  projectileSpeed: 70,
  damage: 8,
  spread: 0.05,
  muzzleForward: 1.2,
};

export const WEAPONS: WeaponCatalog = {
  [PULSE_LASER.id]: PULSE_LASER,
  [ENEMY_BLASTER.id]: ENEMY_BLASTER,
};

/** What a ship carries with no loadout chosen. Becomes a loadout lookup in M3. */
export const DEFAULT_WEAPON = PULSE_LASER;
