// The tick.
//
// One function, one fixed order, no conditionals about what runs. Everything the
// simulation does happens here, which is what makes the whole state machine
// legible — the previous engine's equivalent was a 1,100-line closure where the
// order of operations was whatever the rAF callback happened to do that frame.
//
// The pipeline order is deliberate and will grow, but not change shape:
//
//   intent      read input into per-entity intent
//   flight      move ships (rail follower / free flight)
//   weapons     fire, consume cooldowns
//   waves       release authored waves, then move / aim / fire their enemies
//   spawn       waves and ambient hazards, from the seeded RNG
//   physics     integrate motion
//   collision   broadphase + resolve
//   damage      apply hits, kill entities
//   objectives  win/lose, progression
//   cleanup     flush deferred destruction, advance the clock
//
// Systems marked as not-yet-present land in M1 and M2.

import type { InputFrame } from "@core/input.js";
import { enemyAiSystem } from "./systems/enemies.js";
import { waveSystem } from "./systems/waves.js";
import { firingSystem } from "./systems/firing.js";
import { flightSystem } from "./systems/flight.js";
import { forkSystem } from "./systems/forks.js";
import { lifetimeSystem } from "./systems/lifetime.js";
import { motionSystem } from "./systems/motion.js";
import { collisionSystem } from "./systems/collision.js";
import { objectivesSystem } from "./systems/objectives.js";
import { spawnSystem } from "./systems/spawn.js";
import { stopSystem } from "./systems/stops.js";
import type { SimWorld } from "./world.js";

/**
 * Input for one tick, indexed by player slot. A missing entry means "that player
 * sent nothing for this tick" and is treated as neutral rather than as a repeat of
 * their last frame — a dropped packet should not hold the trigger down.
 */
export type TickInputs = ReadonlyArray<InputFrame | undefined>;

/**
 * Advances the world by exactly one tick.
 *
 * Pure with respect to everything outside `world`: same world state plus same
 * inputs always produces the same next state. That property is what the golden
 * replay tests assert, and what makes client-side prediction possible at all.
 */
export function stepSim(world: SimWorld, inputs: TickInputs): void {
  // Stops run BEFORE flight: flight advances the rail, so deciding afterwards would
  // let the party sail past a stop waypoint before being pulled back.
  stopSystem(world);
  flightSystem(world, inputs);
  // After flight, because flight is what advances `railS` past a commit point. Safe to
  // switch course here precisely because of the commit rule: at `commitS` every course
  // through the fork has identical geometry, so the position flight just wrote is the
  // one the new course would have written.
  forkSystem(world);
  firingSystem(world, inputs);
  // Waves release before enemies think, so one arriving this tick already holds its
  // station rather than spending a tick at the origin. Both run before `spawn`, which
  // is the only one of the three that draws from `world.rng` — keeping the one
  // stream-consuming system last in the group means a change to enemy behaviour can
  // never shift the ambient field, whatever else it does.
  waveSystem(world);
  enemyAiSystem(world);
  spawnSystem(world);
  motionSystem(world);
  // After motion, so a projectile is swept over the distance it actually travelled.
  collisionSystem(world);
  lifetimeSystem(world);
  objectivesSystem(world);

  // Deferred destruction is applied once, after every system has had its look at a
  // consistent world. Destroying inline would swap an unvisited row into a slot an
  // in-progress loop had already passed.
  world.ecs.flushDestroyed();

  world.tick++;
}

/** Runs `count` ticks, pulling each tick's inputs from `inputsFor`. */
export function stepSimMany(
  world: SimWorld,
  count: number,
  inputsFor: (tick: number) => TickInputs,
): void {
  for (let i = 0; i < count; i++) stepSim(world, inputsFor(world.tick));
}
