// Run outcome.
//
// The old game's rule, unchanged: arriving at the final waypoint alive is a win,
// being destroyed is a loss (`railRun.js` `finish(didWin)`).
//
// One co-op change. "Destroyed" now means the WHOLE PARTY is down, not one player —
// a six-player run cannot end because one person flew into a rock. Reviving downed
// players is M2 content; for now they simply stop contributing.

import type { SimWorld } from "../world.js";

/** How close to the end of the rail counts as arriving. */
const ARRIVAL_EPSILON = 1e-3;

export function objectivesSystem(world: SimWorld): void {
  if (world.outcome !== "running") return;

  const rail = world.rail;
  if (!rail) return;
  const course = rail.courses[world.courseId];
  if (!course) return;

  const { ship } = world.components;

  // A party with no ships at all has not lost — it has not started. Guarding this
  // keeps a world that is still being set up from finishing on its first tick.
  let anyShips = false;
  let anyAlive = false;
  for (let slot = 0; slot < world.shipBySlot.length; slot++) {
    const entity = world.shipBySlot[slot];
    if (entity === undefined || !world.ecs.isAlive(entity)) continue;
    const s = ship.row(entity);
    if (s < 0) continue;
    anyShips = true;
    if (ship.columns.health[s]! > 0) anyAlive = true;
  }

  if (anyShips && !anyAlive) return finish(world, false);
  if (anyAlive && world.railS >= course.length - ARRIVAL_EPSILON) return finish(world, true);
}

function finish(world: SimWorld, won: boolean): void {
  world.outcome = won ? "won" : "lost";
  world.events.push({ type: "runFinished", won, tick: world.tick });
}
