// The HUD, as a pure model over simulation state.
//
// Split deliberately in two. `hudModel` reads the world and returns numbers and
// strings; `createHud` (in `hudView.ts`) draws them. Nothing in this file touches the
// DOM, which is what lets the interesting half be tested headlessly — and the
// interesting half really is all of it, because everything a HUD does is arithmetic
// over state the simulation already holds.
//
// It is a READ. The HUD is downstream of everything, and a model that nudged state
// would make the replay fingerprint depend on whether anyone was looking at the
// screen — which in multiplayer means a host and a headless client diverge.

import { ticksToSeconds } from "@core/loop.js";
import { clamp } from "@core/math/index.js";
import { AIM_MODES, VIEW_MODES, type AimMode, type ViewMode } from "@sim/flight.js";
import type { RunOutcome, SimWorld } from "@sim/world.js";

export interface HudModel {
  readonly health: number;
  readonly maxHealth: number;
  /** `health / maxHealth`, clamped to [0, 1] — a bar width, not a raw ratio. */
  readonly healthFraction: number;
  readonly hazardKills: number;
  readonly enemyKills: number;
  /** Distance along the CURRENT course, as [0, 1]. */
  readonly progress: number;
  readonly outcome: RunOutcome;
  readonly held: boolean;
  /** What the stop is asking for, or null. Live — a destroy-N counts down. */
  readonly heldLabel: string | null;
  /** The EFFECTIVE aim mode, including one a stop is forcing over the player's. */
  readonly aimMode: AimMode;
  readonly viewMode: ViewMode;
  readonly wavesReleased: number;
  readonly wavesTotal: number;
  /** Banked this run. What M3's shop will spend. */
  readonly credits: number;
}

/** Reads the world into a HUD model. Pure. */
export function hudModel(world: SimWorld, slot = 0): HudModel {
  const { ship, viewState } = world.components;
  const entity = world.shipBySlot[slot];
  const s = entity === undefined ? -1 : ship.row(entity);
  const v = entity === undefined ? -1 : viewState.row(entity);

  const stats = world.statsFor(slot);
  const maxHealth = stats.maxHealth;
  // An empty slot reads as an empty hull rather than throwing: the HUD is drawn every
  // frame including the ones where a player has not joined yet.
  const health = s < 0 ? 0 : ship.columns.health[s]!;

  const course = world.rail?.courses[world.courseId];
  // Guarding the length as well as the rail: a zero-length course would divide to
  // Infinity and paint a full bar on a run that has not started.
  const progress =
    course && course.length > 0 ? clamp(world.railS / course.length, 0, 1) : 0;

  return {
    health,
    maxHealth,
    // Clamped here rather than in the renderer, so every renderer gets it right.
    // Health is signed so overkill is representable; a bar of negative width is not.
    healthFraction: maxHealth > 0 ? clamp(health / maxHealth, 0, 1) : 0,
    hazardKills: world.hazardsDestroyed,
    enemyKills: world.enemiesDestroyed,
    progress,
    outcome: world.outcome,
    held: world.stop.active,
    heldLabel: world.stop.active ? stopLabel(world) : null,
    // The EFFECTIVE mode. A stop overrides the player's own toggle while parked, and
    // showing the preference instead would tell them the opposite of what is true.
    aimMode: world.forcedAimMode ?? (v < 0 ? "free" : AIM_MODES[viewState.columns.aimMode[v]!] ?? "free"),
    viewMode: v < 0 ? "cockpit" : VIEW_MODES[viewState.columns.viewMode[v]!] ?? "cockpit",
    wavesReleased: world.nextWave,
    wavesTotal: world.waves.length,
    credits: world.credits,
  };
}

/**
 * What the parked rail is asking for, counted down live.
 *
 * A static caption would be worse than useless on a destroy-N stop: the player needs
 * to know how many are LEFT, and the number the stop measures against is a baseline
 * captured on arrival rather than the raw kill count.
 */
function stopLabel(world: SimWorld): string | null {
  const course = world.rail?.courses[world.courseId];
  const spec = course?.waypointAt(world.stop.waypoint).stop;
  if (!spec) return null;

  switch (spec.advance.type) {
    case "destroyed": {
      const done = world.hazardsDestroyed - world.stop.killBaseline;
      return `DESTROY ${Math.max(0, spec.advance.count - done)}`;
    }
    case "time": {
      const elapsed = ticksToSeconds(world.stop.elapsedTicks, world.hz);
      return `HOLD ${Math.max(0, Math.ceil(spec.advance.seconds - elapsed))}`;
    }
    case "damage":
      return "TAKE A HIT";
  }
}
