// Pickup maths, as pure functions.
//
// ── The randomness rule, a fourth time ───────────────────────────────────────────
//
// Whether a destroyed enemy drops anything is CONDITIONAL on the player: it happens
// only because they shot something, which depends on where they flew and what they
// aimed at. So the roll cannot come from `world.rng` — and specifically not from
// `rng.fork()`, which reads the parent's state and therefore advances it. Forking per
// kill would make every later ambient hazard placement depend on the player's aim.
//
// This is the same argument as `sim/split.ts` (rocks breaking), `sim/enemy.ts` (enemies
// firing) and the reason wave formations are geometry rather than scatter. Four
// subsystems, one rule, and it has cost nothing to follow each time. `mixSeed` derives
// a stream from the dying entity's identity and touches nothing.

import { entityGeneration, entityIndex, type Entity } from "@core/ecs.js";
import { mixSeed, Rng } from "@core/rng.js";
import type { PickupDrop } from "@content/schemas/pickup.js";

/** Salt, so a kill's drop roll is not the same stream as its debris or its shots. */
const PICKUP_STREAM = 0x7069_636b;

/**
 * A random stream belonging to one entity's death on one tick.
 *
 * Generation is mixed in alongside the index because entity indices are recycled:
 * without it, the drone that inherits a dead one's slot would roll identically.
 */
export function pickupRngFor(entity: Entity, tick: number, seed: number): Rng {
  return new Rng(
    mixSeed(seed, tick, entityIndex(entity), entityGeneration(entity), PICKUP_STREAM),
  );
}

/**
 * Whether a drop happens, from a stream derived above.
 *
 * Takes the `Rng` rather than deriving it, so the caller decides identity and this
 * stays a pure predicate — and so a spec can drive it with a known stream.
 */
export function rollsDrop(drop: PickupDrop, rng: Rng): boolean {
  // `< chance` rather than `<=`: a chance of 0 must never drop, and `float()` can
  // return exactly 0.
  return rng.float() < drop.chance;
}
