// The per-tick event queue.
//
// Events are the ONLY channel from the simulation to the rest of the game besides
// raw state. A system never calls into the renderer, the audio mixer, or the HUD; it
// pushes `{ type: "hit", … }` and moves on. That indirection is what makes VFX and
// audio automatically correct for remote players in multiplayer — a client renders
// an explosion because an event says one happened, not because its local code path
// happened to run.
//
// `core` stays generic over the event type; `sim` declares the actual union.

export class EventQueue<E> {
  private items: E[] = [];

  /**
   * When muted, `push` is a no-op.
   *
   * This exists for client-side prediction. After a host snapshot arrives, the
   * client rewinds and re-simulates its unacknowledged input frames — but those
   * ticks already fired their events the first time round. Re-simulating with the
   * queue muted keeps the state correction silent instead of replaying every
   * explosion sound several times a second.
   */
  muted = false;

  push(event: E): void {
    if (!this.muted) this.items.push(event);
  }

  /** Events accumulated since the last `clear()`, in push order. */
  peek(): readonly E[] {
    return this.items;
  }

  /**
   * Hands over the accumulated events and empties the queue.
   *
   * Note the queue is NOT cleared per tick: the simulation may run several ticks
   * between two rendered frames, and the consumer must see all of them. Ownership
   * of the returned array passes to the caller.
   */
  drain(): E[] {
    if (this.items.length === 0) return [];
    const out = this.items;
    this.items = [];
    return out;
  }

  clear(): void {
    this.items.length = 0;
  }

  get length(): number {
    return this.items.length;
  }

  /** Runs `fn` with the queue muted, then restores the previous mute state. */
  silently<T>(fn: () => T): T {
    const previous = this.muted;
    this.muted = true;
    try {
      return fn();
    } finally {
      this.muted = previous;
    }
  }
}
