// Waypoint stops — the rail parks and the player must clear a condition to advance.
//
// The state a parked rail carries. The runtime lives in `systems/stops.ts`; the
// AUTHORED shape (`StopSpec`) lives in `@content/schemas/level.js` and is re-exported
// here so call sites can keep reaching for a stop's spec and its state together.

export type { StopAdvance, StopMode, StopSpec } from "@content/schemas/level.js";

/** Live state of the party's rail hold. Part of the world, not of any entity. */
export interface StopState {
  active: boolean;
  /** Waypoint index being held at, or -1. */
  waypoint: number;
  /** Ticks elapsed since the hold began. The stop's clock is the tick counter. */
  elapsedTicks: number;
  /** Kill count when the hold began, so `destroyed` counts kills DURING the stop. */
  killBaseline: number;
  /** Set once the ship has taken damage during this hold. */
  damaged: boolean;
}

export const createStopState = (): StopState => ({
  active: false,
  waypoint: -1,
  elapsedTicks: 0,
  killBaseline: 0,
  damaged: false,
});
