// The difficulty fold.
//
// Difficulty is applied by REWRITING CONTENT, once, before the run starts — never by a
// branch inside a system. `sim` has no idea which difficulty is being played, which is
// what keeps the replay hash a function of the world alone and keeps every system from
// growing a difficulty argument.
//
// It is the same shape as `stats.ts`'s upgrade fold, and deliberately so: both take
// authored defs plus a set of modifiers and produce the defs the run actually uses. The
// difference is only which knobs they turn.
//
// ── Why the player's weapon is safe from `scaleEnemyWeapons` ──────────────────
//
// The player's weapon comes from RESOLVED STATS (`systems/firing.ts` reads
// `world.statsFor(slot).weapon`, folded from the catalog handed to `resolveShipStats`),
// while an enemy's comes from `world.weaponCatalog`. They are two different lookups, so
// scaling the world catalog reaches enemies and nothing else — even if a difficulty
// were ever authored where the two shared a weapon id.

import type { DifficultyDef } from "@content/schemas/difficulty.js";
import type { EnemyDef } from "@content/schemas/enemy.js";
import type { ShipDef } from "@content/schemas/ship.js";
import type { WeaponCatalog } from "@content/schemas/weapon.js";

/**
 * Rounds a scaled integer stat, never below one.
 *
 * Rounding happens HERE, at the fold, and never where the value is read — the same
 * rule `resolveShipStats` states for `fireIntervalTicks`, and for the same reason: two
 * code paths that each rounded at use would eventually disagree. The floor of 1 is what
 * stops an aggressive scale from producing an enemy with no health, which would die to
 * nothing at all and look like a spawning bug.
 */
const scaleInt = (value: number, scale: number): number => Math.max(1, Math.round(value * scale));

/** The hull the player flies with. Scaled BEFORE the upgrade fold — see the def's note. */
export function scaleShip(ship: ShipDef, difficulty: DifficultyDef): ShipDef {
  if (difficulty.hullScale === 1) return ship;
  return { ...ship, maxHealth: scaleInt(ship.maxHealth, difficulty.hullScale) };
}

/** Enemy toughness and how much flying into one costs. */
export function scaleEnemies(
  enemies: readonly EnemyDef[],
  difficulty: DifficultyDef,
): readonly EnemyDef[] {
  if (difficulty.enemyHealthScale === 1 && difficulty.contactDamageScale === 1) return enemies;
  // Mapped in place rather than filtered or reordered: this array's ORDER is the
  // `defId` stored on every enemy instance and part of the replay fingerprint.
  return enemies.map((def) => ({
    ...def,
    health: scaleInt(def.health, difficulty.enemyHealthScale),
    contactDamage: scaleInt(def.contactDamage, difficulty.contactDamageScale),
  }));
}

/** How hard an enemy's shot hits. Only the world catalog — see the header. */
export function scaleEnemyWeapons(
  weapons: WeaponCatalog,
  difficulty: DifficultyDef,
): WeaponCatalog {
  if (difficulty.enemyDamageScale === 1) return weapons;
  const scaled: Record<string, WeaponCatalog[string]> = {};
  for (const [id, weapon] of Object.entries(weapons)) {
    scaled[id] = { ...weapon, damage: scaleInt(weapon.damage, difficulty.enemyDamageScale) };
  }
  return scaled;
}

/** How densely the ambient field seeds. Not rounded — it is a rate, not a count. */
export const scaleHazardRate = (rate: number, difficulty: DifficultyDef): number =>
  rate * difficulty.hazardRateScale;
