// Rock silhouettes.
//
// Every hazard used to be the same `IcosahedronGeometry(1, 0)` at the same identity
// rotation, so a field of rocks was a field of clones — the first thing anyone noticed
// when the game was finally flown. This builds a small set of distinct, lumpy solids
// once at load.
//
// Two constraints shape the approach:
//
//   * Variety must not cost draw calls. Hazards are drawn as `InstancedMesh`, one per
//     geometry, so the number of variants is the number of draw calls for the whole
//     field. A handful is free; per-rock geometry is not.
//   * The jitter must be baked, not per-instance. A vertex displaced at build time
//     costs nothing at runtime; displacing per instance would mean per-instance
//     geometry, which is exactly what instancing exists to avoid.
//
// The jitter uses its own seeded RNG rather than `Math.random`. Nothing in `view` is
// bound by the simulation's determinism rules, but a rock that looked different on
// every page load would make screenshot comparison useless and bug reports unrepeatable.

import { IcosahedronGeometry, type BufferGeometry } from "three";
import { Rng } from "@core/rng.js";

/**
 * Fraction of the radius a vertex may be pushed in or out.
 *
 * Tuned by eye against a screenshot. Neighbouring vertices are displaced
 * independently, so on a subdivided solid this quickly stops reading as "lumpy rock"
 * and starts reading as "shattered crystal" — 0.28 was visibly too spiky.
 */
const JITTER = 0.17;

/**
 * Builds `count` lumpy unit-radius rocks.
 *
 * Subdivision alternates: a subdivided icosahedron has more, smaller facets and reads
 * as a different KIND of rock rather than the same rock re-jittered, which is what
 * makes a handful of variants feel like more than a handful.
 */
export function createRockGeometries(count: number, seed = 0x5eed): BufferGeometry[] {
  const rng = new Rng(seed);
  const geometries: BufferGeometry[] = [];

  for (let i = 0; i < count; i++) {
    const geometry = new IcosahedronGeometry(1, i % 2);
    const positions = geometry.getAttribute("position");

    // Displace along each vertex's own normal — which, on a unit-radius solid centred
    // at the origin, is the vertex direction itself. Scaling rather than adding keeps
    // the rock convex and stops a big displacement from turning it inside out.
    for (let v = 0; v < positions.count; v++) {
      const scale = 1 + rng.range(-JITTER, JITTER);
      positions.setXYZ(
        v,
        positions.getX(v) * scale,
        positions.getY(v) * scale,
        positions.getZ(v) * scale,
      );
    }

    positions.needsUpdate = true;
    // Flat shading reads the face normals, so they have to be rebuilt after moving
    // vertices or the lighting still describes the sphere this used to be.
    geometry.computeVertexNormals();
    geometries.push(geometry);
  }

  return geometries;
}
