// The ship catalog.
//
// ⚠️ EVERY NUMBER HERE IS THE VALUE THE SIMULATION ALREADY USED as a hardcoded
// constant, moved rather than retuned. That is the whole point of this step: routing
// health, radius, box speed and aim rate through the upgrade fold must change no
// behaviour at all, and the evidence is that the golden replay hashes do not move.
//
// Where each came from:
//
//   maxHealth 100  `world.spawnShip` wrote a literal 100
//   radius    1    `SHIP_RADIUS` in `systems/collision.ts`
//   boxSpeed  4    `BOX_MOVE` in `content/tuning/flight.ts`
//   aimRate   2    `AIM_RATE` in the same file
//
// `BOX_MOVE` and `AIM_RATE` stay where they are and are IMPORTED here rather than
// copied. They are the flight model's tuning, hard-won and converted from the old
// engine's per-millisecond rates; duplicating the literals would mean a retune of the
// flight feel silently failing to reach the ship that flies it.

import { AIM_RATE, BOX_MOVE } from "../tuning/flight.js";
import type { ShipCatalog, ShipDef } from "../schemas/ship.js";
import { PULSE_LASER } from "../weapons/index.js";

export const SCOUT: ShipDef = {
  id: "ship.scout",
  maxHealth: 100,
  radius: 1,
  boxSpeed: BOX_MOVE,
  aimRate: AIM_RATE,
  weapon: PULSE_LASER.id,
};

export const SHIPS: ShipCatalog = {
  [SCOUT.id]: SCOUT,
};

/** What a player flies with no hull chosen. Becomes a loadout lookup with the save. */
export const DEFAULT_SHIP = SCOUT;
