// Touch controls — the PURE half.
//
// Same split as `hud.ts` / `hudView.ts`, and for the same reason: every decision a
// touch control makes is arithmetic over pointer coordinates — which zone a press
// landed in, how far the thumb has travelled from where it started, whether that
// distance is past the deadzone, what the axes read once clamped — and none of it
// needs a DOM to be worth testing. `touchView.ts` owns the elements and the listeners
// and makes no decisions at all.
//
// That matters more here than it did for the HUD. The HUD is read-only; this is an
// INPUT path, so a mistake in it is indistinguishable from a flight-model bug when you
// are holding the phone. Being able to assert "thumb 40px left of the origin, on a
// 90px stick, reads -0.44 with the deadzone applied" without a browser is what keeps
// the diagnosis honest.
//
// The output is deliberately NOT an `InputFrame`. This produces intent; `controls.ts`
// merges it with the keyboard and builds the frame, so quantization happens exactly
// once, in one place, for every input source (see the header of `core/input.ts`).

import { Button } from "@sim/buttons.js";

/** Where a press landed. The zones are computed in `layout`, below. */
export type Zone = "stick" | "fire" | "boost" | "brake" | "view" | "aim";

/** An axis-aligned rectangle in CSS pixels. */
export interface Rect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export const rectContains = (r: Rect, x: number, y: number): boolean =>
  x >= r.x && x <= r.x + r.width && y >= r.y && y <= r.y + r.height;

/**
 * The chip buttons, in hit-test order.
 *
 * Order is load-bearing: the fire zone is the whole right half of the screen, so every
 * chip sits INSIDE it. Hit-testing the chips first is what stops "boost" from also
 * reading as "fire" — a press belongs to exactly one zone, decided once on pointerdown
 * and never revisited while that finger is down.
 */
const CHIPS: readonly Zone[] = ["view", "aim", "boost", "brake"];

/** Which button bit each zone contributes. `stick` contributes none. */
const ZONE_BUTTON: Partial<Record<Zone, number>> = {
  fire: Button.Fire,
  boost: Button.Boost,
  brake: Button.Brake,
  view: Button.ViewToggle,
  aim: Button.AimMode,
};

export interface TouchLayout {
  readonly width: number;
  readonly height: number;
  /** Radius of a fully deflected stick, in CSS pixels. */
  readonly stickRadius: number;
  /** The left region that opens a stick. */
  readonly stickZone: Rect;
  /** The right region that fires. Chips sit inside it and win the hit test. */
  readonly fireZone: Rect;
  readonly chips: Readonly<Record<"boost" | "brake" | "view" | "aim", Rect>>;
  /** Where the idle "put your thumb here" hint is drawn. */
  readonly stickHome: { readonly x: number; readonly y: number };
}

/** Fraction of the stick radius that reads as zero. */
export const DEADZONE = 0.15;

const CHIP = 56;
const CHIP_GAP = 12;

const clamp = (v: number, lo: number, hi: number): number => (v < lo ? lo : v > hi ? hi : v);

/**
 * Computes the control layout for a viewport.
 *
 * `insetBottom` / `insetRight` are the safe-area insets — the home indicator on a
 * notched phone, which sits over the bottom ~34px in landscape and will happily eat a
 * chip. They arrive from CSS `env(safe-area-inset-*)`, read in the view.
 */
export function layout(
  width: number,
  height: number,
  insetBottom = 0,
  insetRight = 0,
  insetLeft = 0,
): TouchLayout {
  // Scaled to the SHORT edge, so the stick is the same size relative to a thumb on a
  // phone in landscape as on a tablet, rather than growing with the long edge.
  const stickRadius = clamp(Math.min(width, height) * 0.18, 44, 110);

  const right = width - insetRight;
  const bottom = height - insetBottom;

  // A 2×2 block in the bottom-right corner. Two constraints pin it there and both were
  // learned by putting it somewhere else first:
  //
  // The TOP right is where the HUD's stats block lives (`.sw-hud-stats`, top/right 14),
  // and the touch overlay paints above the HUD — so chips up there sit squarely on the
  // rock/kill/wave counters and hide the numbers the player is flying by.
  //
  // The bottom right is also simply where the right thumb already is. These are toggles
  // reached mid-flight, and a reach to the far corner of a phone held in two hands
  // means letting go of the stick.
  const col1 = right - CHIP - CHIP_GAP;
  const col0 = right - CHIP * 2 - CHIP_GAP * 2;
  const row1 = bottom - CHIP - CHIP_GAP;
  const row0 = bottom - CHIP * 2 - CHIP_GAP * 2;

  return {
    width,
    height,
    stickRadius,
    stickZone: { x: 0, y: 0, width: width * 0.5, height },
    fireZone: { x: width * 0.5, y: 0, width: width * 0.5, height },
    chips: {
      // Held buttons on the bottom row, nearest the thumb; toggles above them.
      boost: { x: col1, y: row1, width: CHIP, height: CHIP },
      brake: { x: col0, y: row1, width: CHIP, height: CHIP },
      view: { x: col1, y: row0, width: CHIP, height: CHIP },
      aim: { x: col0, y: row0, width: CHIP, height: CHIP },
    },
    stickHome: {
      x: insetLeft + Math.max(stickRadius + 24, width * 0.14),
      y: bottom - Math.max(stickRadius + 24, height * 0.26),
    },
  };
}

/** A finger, and what it is doing. */
interface Tracked {
  readonly zone: Zone;
  /** Where the finger went down. The stick's origin — not the layout's home position. */
  readonly originX: number;
  readonly originY: number;
  x: number;
  y: number;
}

/** What the view needs in order to draw the stick. */
export interface StickVisual {
  readonly active: boolean;
  /** Origin in CSS pixels — where the thumb landed. */
  readonly originX: number;
  readonly originY: number;
  /** Knob offset from the origin, in CSS pixels, already clamped to the radius. */
  readonly knobX: number;
  readonly knobY: number;
}

export interface TouchIntent {
  readonly steerX: number;
  readonly steerY: number;
  readonly buttons: number;
}

export class TouchControls {
  private current: TouchLayout;
  private readonly pointers = new Map<number, Tracked>();
  /**
   * Zones pressed since the last `sample`, whether or not the finger is still down.
   *
   * Exactly the latch `Keyboard` keeps, for exactly the same reason: the simulation
   * samples only when a tick runs, so a tap that goes down and up between two ticks is
   * otherwise never observed — and view-toggle and aim-mode are edge-triggered, so
   * they are the two that would silently miss it. On a touchscreen this is not an edge
   * case: a chip tap is routinely shorter than 16ms.
   */
  private readonly tapped = new Set<Zone>();

  constructor(width = 0, height = 0) {
    this.current = layout(width, height);
  }

  get layout(): TouchLayout {
    return this.current;
  }

  resize(width: number, height: number, insetBottom = 0, insetRight = 0, insetLeft = 0): void {
    this.current = layout(width, height, insetBottom, insetRight, insetLeft);
  }

  /** Which zone a point belongs to. Chips win over the region they sit in. */
  zoneAt(x: number, y: number): Zone {
    for (const chip of CHIPS) {
      const rect = this.current.chips[chip as "boost" | "brake" | "view" | "aim"];
      if (rectContains(rect, x, y)) return chip;
    }
    return rectContains(this.current.stickZone, x, y) ? "stick" : "fire";
  }

  down(id: number, x: number, y: number): void {
    const zone = this.zoneAt(x, y);
    this.pointers.set(id, { zone, originX: x, originY: y, x, y });
    this.tapped.add(zone);
  }

  /**
   * Moves a finger.
   *
   * The zone is NOT recomputed. A thumb that starts on the stick and slides into the
   * right half is still steering — re-deciding mid-drag would drop the stick and start
   * firing, which is precisely what happens when you pull hard left-to-right.
   */
  move(id: number, x: number, y: number): void {
    const tracked = this.pointers.get(id);
    if (!tracked) return;
    tracked.x = x;
    tracked.y = y;
  }

  up(id: number): void {
    this.pointers.delete(id);
  }

  /**
   * Drops every finger.
   *
   * For the touch equivalent of the keyboard's blur handler: backgrounding the app, a
   * system gesture, or an incoming call swallows `pointerup`, and without this the ship
   * flies on with the stick pinned. The tap latch is deliberately NOT cleared — a tap
   * immediately before losing the page still happened.
   */
  cancelAll(): void {
    this.pointers.clear();
  }

  private stickPointer(): Tracked | undefined {
    for (const tracked of this.pointers.values()) if (tracked.zone === "stick") return tracked;
    return undefined;
  }

  /** Stick state for the view. Reads nothing the sample does not. */
  stick(): StickVisual {
    const tracked = this.stickPointer();
    if (!tracked) return { active: false, originX: 0, originY: 0, knobX: 0, knobY: 0 };
    const [dx, dy] = this.deflection(tracked);
    return {
      active: true,
      originX: tracked.originX,
      originY: tracked.originY,
      knobX: dx * this.current.stickRadius,
      knobY: dy * this.current.stickRadius,
    };
  }

  /** Zones currently held. For the view's pressed styling. */
  heldZones(): ReadonlySet<Zone> {
    const held = new Set<Zone>();
    for (const tracked of this.pointers.values()) held.add(tracked.zone);
    return held;
  }

  /**
   * Deflection as a unit-disc vector in SCREEN space (y down), deadzone applied.
   *
   * Rescaled past the deadzone rather than merely subtracted, so the axis still reaches
   * 1.0 at full travel — subtracting alone caps a fully deflected stick at 0.85 and the
   * ship never quite reaches the edge of its box.
   */
  private deflection(tracked: Tracked): [number, number] {
    const dx = tracked.x - tracked.originX;
    const dy = tracked.y - tracked.originY;
    const distance = Math.hypot(dx, dy);
    if (distance <= 0) return [0, 0];

    const unit = Math.min(distance / this.current.stickRadius, 1);
    if (unit <= DEADZONE) return [0, 0];
    const scaled = (unit - DEADZONE) / (1 - DEADZONE);
    return [(dx / distance) * scaled, (dy / distance) * scaled];
  }

  /**
   * The current intent, and the point at which the tap latch is consumed.
   *
   * Call this exactly once per tick, like `Keyboard.sample`.
   */
  sample(): TouchIntent {
    let steerX = 0;
    let steerY = 0;
    const stick = this.stickPointer();
    if (stick) {
      const [dx, dy] = this.deflection(stick);
      steerX = dx;
      // Screen y grows downward; the simulation's steerY is positive UP, matching the
      // up-arrow. Flipping it anywhere else would make the two input paths disagree
      // about which way is up, which reads as an inverted-Y bug in the flight model.
      //
      // Guarded against `dy === 0` so a centred stick reads +0 rather than -0. The
      // wire does not care — `Math.round(-0 * 32767)` writes a 0 int16 — but a signed
      // zero leaking into the input stream is the kind of thing that later shows up as
      // two peers hashing the same frame differently, and it costs one comparison to
      // never find out the hard way.
      steerY = dy === 0 ? 0 : -dy;
    }

    let buttons = 0;
    for (const tracked of this.pointers.values()) buttons |= ZONE_BUTTON[tracked.zone] ?? 0;
    for (const zone of this.tapped) buttons |= ZONE_BUTTON[zone] ?? 0;

    // Cleared after the intent is built, so exactly one tick sees each tap and the next
    // tick sees the falling edge that re-arms the toggle.
    this.tapped.clear();
    return { steerX, steerY, buttons };
  }
}
